#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=8

# ── Wizard-local helpers (the library above is untouched) ──────────────────

SELF_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd -P)"
SELF_CMD="$SELF_DIR/$(basename -- "${BASH_SOURCE[0]}")"
REPO_ROOT="$(cd -- "$SELF_DIR/../.." && pwd -P)"
SIDECAR_PY="$REPO_ROOT/scripts/eval/coderank_sidecar.py"
PROTOCOL_DOC="$REPO_ROOT/docs/eval/retrieval/coderank-sidecar-protocol.md"

# Resumable state. Contains only non-secret values (paths, digests, endpoint).
# `.env.*` is already gitignored in this repo, so it never reaches a commit.
ENV_FILE="${CODERANK_WIZARD_STATE:-$REPO_ROOT/.env.coderank-wizard}"

WORK="$(mktemp -d "${TMPDIR:-/tmp}/coderank-wizard.XXXXXX")"
GOCHECK_DIR=""
cleanup() {
  rm -rf -- "$WORK"
  [[ -n "$GOCHECK_DIR" && -d "$GOCHECK_DIR" ]] && rm -rf -- "$GOCHECK_DIR"
  return 0
}
trap cleanup EXIT

ok()   { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
head2() { printf '\n  %s%s%s\n' "$BOLD" "$1" "$RESET"; }

# fail "what failed" "why it matters" "exact next action" — the fail-closed exit.
fail() {
  printf '\n  %s✗ %s%s\n' "$RED" "$1" "$RESET"
  if [[ -n "${2:-}" ]]; then printf '  %swhy it matters:%s %s\n' "$DIM" "$RESET" "$2"; fi
  if [[ -n "${3:-}" ]]; then printf '  %snext action:%s   %s\n'  "$DIM" "$RESET" "$3"; fi
  printf '\n  %sStopping here. Nothing past this check was done or changed.%s\n' "$DIM" "$RESET"
  printf '  %sAfter fixing it, re-run — completed work is remembered:%s\n' "$DIM" "$RESET"
  printf '    %s\n\n' "$SELF_CMD"
  exit 1
}

# ask_valid KEY "Prompt" REGEX "hint" — re-asks until the value matches.
ask_valid() {
  local key="$1" prompt="$2" pattern="$3" hint="$4" tries=0 value=""
  while :; do
    ask "$key" "$prompt"
    value="${!key}"
    if [[ -n "$value" && "$value" =~ $pattern ]]; then return 0; fi
    tries=$((tries + 1))
    warn "not accepted: $hint"
    if (( tries >= 5 )); then
      fail "no usable value for $key after $tries attempts" \
           "every manifest pin is load-bearing; a guess here produces a manifest that fails validation later" \
           "$hint"
    fi
  done
}

# shq VALUE — shell-quote a value so printed commands are copy-pasteable.
shq() { printf '%q' "$1"; }

# run_py NAME ARGS... — run one of the generated helpers with the repo on
# PYTHONPATH so it imports the reference sidecar module itself.
run_py() {
  local name="$1"; shift
  PYTHONPATH="$REPO_ROOT${PYTHONPATH:+:$PYTHONPATH}" python3 "$WORK/$name" "$@"
}

# ── Generated Python helpers. Each one *calls* the reference sidecar module;
#    none of them reimplements a digest, a manifest rule, or a tree scan. ──

cat > "$WORK/preflight.py" <<'PY'
"""Check the interpreter and the pinned runtime distributions. Installs nothing."""
import json
import sys

MIN = (3, 11)
if sys.version_info < MIN:
    print(f"python-too-old\t{'.'.join(map(str, sys.version_info[:3]))}", file=sys.stderr)
    raise SystemExit(2)

try:
    from scripts.eval import coderank_sidecar as sc
except Exception as exc:  # noqa: BLE001 - surfaced verbatim to the operator
    print(f"import-failed\t{type(exc).__name__}: {exc}", file=sys.stderr)
    raise SystemExit(3)

import importlib.metadata as md

missing = []
found = {}
for name in sc.RUNTIME_PACKAGES:
    try:
        found[name] = md.version(name)
    except md.PackageNotFoundError:
        missing.append(name)

if missing:
    print("missing-distributions\t" + " ".join(missing), file=sys.stderr)
    for name, version in sorted(found.items()):
        print(f"  present: {name} {version}", file=sys.stderr)
    raise SystemExit(4)

# Authoritative source: the module's own inventory + digest, not ours.
versions = sc.runtime_versions()
out = {
    "python": versions["python"],
    "runtime_version": versions["sentence-transformers"],
    "runtime_sha256": sc.runtime_digest(versions),
    "versions": versions,
    "protocol": sc.PROTOCOL,
}
outdir = sys.argv[1]
with open(outdir + "/runtime.json", "w", encoding="utf-8") as stream:
    json.dump(out, stream)
for name in sorted(versions):
    print(f"  {name:<22} {versions[name]}")
print(f"\n  runtime.name           sentence-transformers")
print(f"  runtime.version        {out['runtime_version']}")
print(f"  runtime.sha256         {out['runtime_sha256']}")
PY

cat > "$WORK/treecheck.py" <<'PY'
"""Sanity-check the operator's model tree and compute the documented digest pins.

Every structural rule enforced here comes from the reference module itself
(`local_directory`, `artifact_files`, `verify_local_custom_code`) or from the
protocol document's explicit "immutable snapshot, no caches inside it" rule.
Digests are produced by `tree_digest` / `tokenizer_digest`; nothing is rehashed
locally.
"""
import hashlib
import json
import os
import stat
import sys
from pathlib import Path

from scripts.eval import coderank_sidecar as sc

raw, outdir = sys.argv[1], sys.argv[2]


def die(kind, message, detail=""):
    print(f"{kind}\t{message}", file=sys.stderr)
    if detail:
        print(detail, file=sys.stderr)
    raise SystemExit(1)


given = Path(raw)
if not given.is_absolute():
    die("not-absolute", f"{raw} is not an absolute path")

# 1. Root shape: absolute, a real directory, not itself a symlink.
try:
    root = sc.local_directory(given)
except Exception as exc:  # noqa: BLE001
    hint = ""
    if given.is_symlink():
        hint = ("  The path itself is a symlink. Hugging Face hub snapshot directories are\n"
                "  symlink farms; point at a materialised copy instead.")
    die("bad-root", str(exc), hint)

if str(root) != str(given):
    print(f"  note: canonical path is {root}")
    print(f"        (given {given}; OS ancestor aliases such as macOS /var are resolved)")

# 2. Caches / VCS / OS debris inside the tree. The protocol requires an
#    immutable snapshot with no caches inside it: anything here changes
#    model.sha256 underneath a running sidecar.
CACHE_DIRS = {"__pycache__", ".git", ".cache", ".huggingface", ".locks",
              ".ipynb_checkpoints", ".mypy_cache", ".pytest_cache"}
HUB_DIRS = {"blobs", "snapshots", "refs"}
dirty, hubbish = [], []
for dirpath, dirnames, filenames in os.walk(root):
    rel = Path(dirpath).relative_to(root)
    for name in list(dirnames):
        if name in CACHE_DIRS:
            dirty.append(str(rel / name) + "/")
        if name in HUB_DIRS and rel == Path("."):
            hubbish.append(str(rel / name) + "/")
    for name in filenames:
        if name == ".DS_Store" or name.endswith((".pyc", ".pyo", ".lock", ".incomplete")):
            dirty.append(str(rel / name))

if hubbish:
    die("hub-cache",
        "this looks like a Hugging Face hub cache directory, not an immutable snapshot",
        "  found at the root: " + ", ".join(sorted(hubbish)) + "\n"
        "  A hub cache stores weights in blobs/ and exposes them through symlinks\n"
        "  under snapshots/<revision>/, which the sidecar rejects on principle.")
if dirty:
    die("cache-inside-tree",
        f"{len(dirty)} cache/VCS/OS artefact(s) live inside the model tree",
        "  " + "\n  ".join(sorted(dirty)[:20]) +
        ("\n  ..." if len(dirty) > 20 else ""))

# 3. Symlinks and special files anywhere in the tree (the module's own rule).
#    Enumerate offenders first so the failure names them.
offenders = []
for path in root.rglob("*"):
    mode = path.lstat().st_mode
    if stat.S_ISLNK(mode):
        offenders.append(f"symlink  {path.relative_to(root)}")
    elif not (stat.S_ISREG(mode) or stat.S_ISDIR(mode)):
        offenders.append(f"special  {path.relative_to(root)}")
if offenders:
    die("symlink-or-special",
        f"{len(offenders)} symlink(s)/special file(s) inside the tree",
        "  " + "\n  ".join(offenders[:20]) + ("\n  ..." if len(offenders) > 20 else ""))

try:
    files = sc.artifact_files(root)
except Exception as exc:  # noqa: BLE001
    die("bad-tree", str(exc))

total_bytes = sum(path.stat().st_size for path in files)

# 4. Custom-code review gate: the same pre-import auto_map / modules.json scan
#    `verify` runs, surfaced now so the operator reviews before ever serving.
try:
    sc.verify_local_custom_code(root)
except Exception as exc:  # noqa: BLE001
    scanned = [str(path.relative_to(root)) for path in files
               if path.name == "modules.json"
               or (path.suffix == ".json" and "config" in path.stem)]
    die("custom-code",
        str(exc),
        "  A config's auto_map or a modules.json entry points outside the verified tree.\n"
        "  trust_remote_code=True executes that code; the sidecar refuses to load it.\n"
        "  Files carrying custom-code targets in this tree:\n    "
        + "\n    ".join(scanned))

# 5. The documented digest recipe — the module's own functions, verbatim.
try:
    model_sha = sc.tree_digest(root)
except Exception as exc:  # noqa: BLE001
    die("model-digest", str(exc))
try:
    tokenizer_sha = sc.tokenizer_digest(root)
except Exception as exc:  # noqa: BLE001
    die("tokenizer-digest", str(exc),
        "  tokenizer.sha256 covers a fixed root-level allowlist and needs at least one\n"
        "  of tokenizer.json, vocab.txt, vocab.json, tokenizer.model, spiece.model,\n"
        "  sentencepiece.bpe.model directly in the model directory.")

instruction_sha = hashlib.sha256(sc.QUERY_INSTRUCTION.encode("utf-8")).hexdigest()

# 6. Advisory evidence for the admission limit. Reading a JSON field is not a
#    capacity proof; the operator still decides.
evidence = {}
for name in ("tokenizer_config.json", "config.json"):
    candidate = root / name
    if candidate.is_file():
        try:
            blob = json.loads(candidate.read_text(encoding="utf-8"))
        except Exception:  # noqa: BLE001
            continue
        if isinstance(blob, dict):
            for key in ("model_max_length", "max_position_embeddings"):
                value = blob.get(key)
                if isinstance(value, int) and 0 < value < 10 ** 7:
                    evidence[f"{name}:{key}"] = value

writable = os.access(root, os.W_OK)

for key, value in (("model_root", str(root)), ("model_sha256", model_sha),
                   ("tokenizer_sha256", tokenizer_sha),
                   ("instruction_sha256", instruction_sha)):
    with open(f"{outdir}/{key}", "w", encoding="utf-8") as stream:
        stream.write(value)

print(f"  files                  {len(files)}")
print(f"  bytes                  {total_bytes}")
print(f"  model.sha256           {model_sha}")
print(f"  tokenizer.sha256       {tokenizer_sha}")
print(f"  query.instruction_sha256")
print(f"                         {instruction_sha}")
if evidence:
    print("\n  declared limits found in the tree (advisory, not a capacity proof):")
    for key in sorted(evidence):
        print(f"    {key} = {evidence[key]}")
if writable:
    print("\n  note: the tree is writable by you. It must stay byte-identical for the")
    print("        lifetime of the sidecar process; any edit invalidates these pins.")
PY

cat > "$WORK/mkmanifest.py" <<'PY'
"""Assemble coderank.json from verified pins, in the documented field order."""
import json
import sys

from scripts.eval import coderank_sidecar as sc

(out_path, endpoint, model_id, model_rev, model_sha, tok_id, tok_rev, tok_sha,
 runtime_version, runtime_sha, max_tokens, reserve, instruction_sha) = sys.argv[1:]

manifest = {
    "schema_version": 1,
    "protocol": sc.PROTOCOL,
    "endpoint": endpoint,
    "model": {"id": model_id, "revision": model_rev, "sha256": model_sha},
    "tokenizer": {"id": tok_id, "revision": tok_rev, "sha256": tok_sha},
    "runtime": {"name": "sentence-transformers", "version": runtime_version,
                "sha256": runtime_sha},
    "dimension": 768,
    "precision": "float32",
    "normalization": "l2",
    "compute": "cpu",
    "admission": {"max_tokens": int(max_tokens), "reserve": int(reserve),
                  "algorithm": "first-n-tokens", "algorithm_version": "1"},
    "query": {
        "id": "coderank-code-search-query",
        "version": "1",
        "instruction": sc.QUERY_INSTRUCTION,
        "instruction_sha256": instruction_sha,
    },
}

# Refuse to write anything the reference validator would reject.
sc.validate_manifest(manifest)

body = json.dumps(manifest, indent=2, ensure_ascii=False) + "\n"
try:
    with open(out_path, "r", encoding="utf-8") as stream:
        if stream.read() == body:
            print("unchanged")
            raise SystemExit(0)
except FileNotFoundError:
    pass
except SystemExit:
    raise
except OSError:
    pass

with open(out_path + ".wizard-tmp", "w", encoding="utf-8") as stream:
    stream.write(body)
import os
os.replace(out_path + ".wizard-tmp", out_path)
print("written")
PY

cat > "$WORK/diagnose.py" <<'PY'
"""Pinpoint which of `verify`'s checks failed. `verify` only prints one line."""
import sys

from scripts.eval import coderank_sidecar as sc

manifest_path, model_dir = sys.argv[1], sys.argv[2]

try:
    with open(manifest_path, "rb") as stream:
        manifest = sc.strict_json(stream.read())
except Exception as exc:  # noqa: BLE001
    print(f"  manifest is not strict JSON: {exc}")
    raise SystemExit(0)

checks = [
    ("manifest schema/profile/endpoint", lambda: sc.validate_manifest(manifest)),
    ("model tree is scannable", lambda: sc.artifact_files(sc.local_directory(model_dir))),
    ("model.sha256 matches the tree", lambda: _eq(
        sc.tree_digest(model_dir), manifest["model"]["sha256"], "model.sha256")),
    ("tokenizer.sha256 matches the tree", lambda: _eq(
        sc.tokenizer_digest(model_dir), manifest["tokenizer"]["sha256"], "tokenizer.sha256")),
    ("local custom code stays inside the tree",
     lambda: sc.verify_local_custom_code(sc.local_directory(model_dir))),
    ("installed runtime matches runtime.{version,sha256}",
     lambda: sc.verify_runtime_versions(manifest["runtime"])),
]


def _eq(observed, pinned, label):
    if observed != pinned:
        raise ValueError(f"{label}: tree is {observed}, manifest pins {pinned}")


for label, check in checks:
    try:
        check()
    except Exception as exc:  # noqa: BLE001
        print(f"  ✗ {label}")
        print(f"      {type(exc).__name__}: {exc}")
        raise SystemExit(0)
    print(f"  ✓ {label}")
print("  all individual checks passed — re-run verify and report the discrepancy.")
PY

cat > "$WORK/attest.py" <<'PY'
"""Validate a /v1/attestation body against the manifest's durable identity."""
import sys

from scripts.eval import coderank_sidecar as sc

body_path, expected_identity = sys.argv[1], sys.argv[2]

with open(body_path, "rb") as stream:
    payload = sc.strict_json(stream.read())

problems = []
expected_keys = {"protocol", "identity_digest", "epoch", "dimension",
                 "peak_rss_bytes", "artifact_bytes", "runtime_threads"}
if not isinstance(payload, dict) or set(payload) != expected_keys:
    got = sorted(payload) if isinstance(payload, dict) else type(payload).__name__
    problems.append(f"unexpected response fields: {got}")
else:
    if payload["protocol"] != sc.PROTOCOL:
        problems.append(f"protocol is {payload['protocol']!r}, expected {sc.PROTOCOL!r}")
    if payload["identity_digest"] != expected_identity:
        problems.append("identity_digest does not match the manifest: the running "
                        "sidecar serves a different embedding space\n"
                        f"      serving:  {payload['identity_digest']}\n"
                        f"      manifest: {expected_identity}")
    if payload["dimension"] != 768:
        problems.append(f"dimension is {payload['dimension']!r}, expected 768")
    if not (isinstance(payload["epoch"], str) and payload["epoch"]):
        problems.append("epoch is missing or empty")
    for name in ("peak_rss_bytes", "artifact_bytes", "runtime_threads"):
        value = payload[name]
        if type(value) is not int or value <= 0:
            problems.append(f"{name} must be a positive exact integer, got {value!r}")

if problems:
    for problem in problems:
        print("    - " + problem, file=sys.stderr)
    raise SystemExit(1)

print(f"  protocol               {payload['protocol']}")
print(f"  identity_digest        {payload['identity_digest']}")
print(f"  epoch                  {payload['epoch']}")
print(f"  dimension              {payload['dimension']}")
print(f"  peak_rss_bytes         {payload['peak_rss_bytes']}")
print(f"  artifact_bytes         {payload['artifact_bytes']}")
print(f"  runtime_threads        {payload['runtime_threads']}")
with open(body_path + ".epoch", "w", encoding="utf-8") as stream:
    stream.write(payload["epoch"])
PY

cat > "$WORK/identity.py" <<'PY'
"""Print the manifest's durable identity digest using the module's own encoder."""
import sys

from scripts.eval import coderank_sidecar as sc

with open(sys.argv[1], "rb") as stream:
    print(sc.identity_digest(sc.strict_json(stream.read())))
PY

# ── Opening frame ─────────────────────────────────────────────────────────
# Not the library's banner(): this wizard opens no browser and captures no
# third-party credentials, so it would promise the wrong thing.
_clear
printf '\n%s%s  CodeRank development sidecar provisioning%s\n' "$BOLD" "$BLUE" "$RESET"
printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
note "GrapHi never downloads model weights, never installs a Python runtime, and"
note "never launches or supervises this sidecar. Those are operator actions by"
note "design. This wizard does none of them either: it tells you exactly what is"
note "needed, verifies what you produced, and stops at the first thing that is"
note "not provably right."
printf '\n'
note "It will: check preconditions, sanity-check your model tree, compute the"
note "documented digest pins, write and validate coderank.json, then hand you the"
note "exact serve command to run in your own terminal."
printf '\n'
note "Nothing is downloaded, installed, or started on your behalf. No secrets are"
note "read or written. Ctrl-C any time: re-running resumes from what is verified."
printf '\n'
note "state file: $ENV_FILE"
note "protocol:   $PROTOCOL_DOC"
printf '\n'
pause "Ready to start?"

# ── Stage 1 ───────────────────────────────────────────────────────────────
stage "Preconditions: interpreter and pinned runtime"

say "The sidecar is an evaluation-only Python 3.11+ tool. It needs an already"
say "installed, pinned runtime. This wizard installs nothing — if something is"
say "missing, you install it yourself and re-run."
printf '\n'

[[ -f "$SIDECAR_PY" ]] || fail \
  "reference sidecar not found at $SIDECAR_PY" \
  "every check below is delegated to that module; without it nothing can be verified" \
  "run this wizard from a checkout of the graphi repository"

command -v python3 >/dev/null 2>&1 || fail \
  "python3 is not on PATH" \
  "the sidecar, the digest recipe, and every verification step are Python 3.11+" \
  "install Python 3.11 or newer and make python3 resolve to it"

command -v curl >/dev/null 2>&1 || fail \
  "curl is not on PATH" \
  "the liveness check reads http://<endpoint>/v1/attestation exactly as the protocol document does" \
  "install curl, then re-run"

head2 "Installed runtime inventory"
set +e
PREFLIGHT_OUT="$(cd "$REPO_ROOT" && run_py preflight.py "$WORK" 2>"$WORK/preflight.err")"
PREFLIGHT_RC=$?
set -e
if (( PREFLIGHT_RC != 0 )); then
  PREFLIGHT_ERR="$(cat "$WORK/preflight.err")"
  case "$PREFLIGHT_ERR" in
    python-too-old*)
      fail "python3 is older than 3.11 ($(python3 --version 2>&1))" \
           "the sidecar uses hashlib.file_digest, which only exists from 3.11; the digest pins cannot be computed at all" \
           "install Python 3.11+ and re-run with that interpreter first on PATH" ;;
    import-failed*)
      printf '  %s\n' "$PREFLIGHT_ERR"
      fail "could not import scripts.eval.coderank_sidecar" \
           "the whole wizard delegates to that module; a broken import means nothing downstream can be trusted" \
           "check the module imports cleanly: cd $(shq "$REPO_ROOT") && python3 -m py_compile scripts/eval/coderank_sidecar.py" ;;
    missing-distributions*)
      MISSING="$(printf '%s' "$PREFLIGHT_ERR" | head -n1 | cut -f2-)"
      printf '%s\n' "$PREFLIGHT_ERR" | tail -n +2
      printf '\n'
      fail "pinned runtime distributions are not installed: $MISSING" \
           "runtime.version and runtime.sha256 pin the exact installed versions; without them the manifest cannot be built, and serve would load an unpinned runtime" \
           "install them yourself into the interpreter you will serve with (the wizard deliberately will not pip install for you), then re-run" ;;
    *)
      printf '  %s\n' "$PREFLIGHT_ERR"
      fail "runtime preflight failed" \
           "an unverified runtime cannot produce a trustworthy runtime.sha256" \
           "resolve the error above and re-run" ;;
  esac
fi
printf '%s\n' "$PREFLIGHT_OUT"

PY_VERSION="$(python3 --version 2>&1)"
RUNTIME_VERSION="$(sed -n 's/.*"runtime_version": *"\([^"]*\)".*/\1/p' "$WORK/runtime.json")"
RUNTIME_SHA256="$(sed -n 's/.*"runtime_sha256": *"\([^"]*\)".*/\1/p' "$WORK/runtime.json")"
[[ -n "$RUNTIME_VERSION" && -n "$RUNTIME_SHA256" ]] || fail \
  "could not read the runtime pins the preflight produced" \
  "runtime.version and runtime.sha256 are manifest fields; empty values would fail validation" \
  "re-run; if it persists, run the digest recipe in $PROTOCOL_DOC by hand"

printf '\n'
ok "$PY_VERSION"
ok "all 7 pinned distributions present and readable"
note "runtime.sha256 is a reproducible version inventory, not a hash of installed"
note "bytes. It does not establish provenance — reviewing that stays yours."

printf '\n'
if confirm "Run the offline contract tests now (no weights, no network, ~seconds)?"; then
  printf '\n'
  if (cd "$REPO_ROOT" && python3 -m unittest scripts.eval.tests.test_coderank_sidecar >"$WORK/tests.log" 2>&1); then
    ok "reference sidecar contract tests pass"
  else
    tail -n 25 "$WORK/tests.log"
    fail "the reference sidecar's own contract tests fail" \
         "the wizard verifies everything through this module; if its tests fail, its digests and manifest rules are not trustworthy" \
         "cd $(shq "$REPO_ROOT") && python3 -m unittest scripts.eval.tests.test_coderank_sidecar -v"
  fi
fi

write_env CODERANK_RUNTIME_VERSION "$RUNTIME_VERSION"
write_env CODERANK_RUNTIME_SHA256 "$RUNTIME_SHA256"
printf '\n'
pause "Preconditions verified. Press Enter to continue."

# ── Stage 2 ───────────────────────────────────────────────────────────────
stage "Locate and sanity-check the model tree"

say "You provision the model tree yourself: obtain it from a source you trust,"
say "review the code and configuration inside it, and materialise it as an"
say "immutable local snapshot. This wizard will not download anything."
printf '\n'
step "Absolute path only — relative paths, hub IDs and URLs are rejected."
step "No symlink at the root and no symlinks anywhere inside the tree."
step "No caches inside it: every regular file, recursively, feeds model.sha256."
step "A Hugging Face hub cache directory (blobs/, snapshots/, refs/) is not a"
say  "    snapshot — materialise a real copy, e.g. with a plain recursive copy that"
say  "    dereferences symlinks."
step "The tree must stay byte-identical for the lifetime of the serving process."
printf '\n'

ask_valid CODERANK_MODEL_DIR "Absolute path to the model directory:" \
  '^/' "the path must start with / (e.g. /srv/models/CodeRankEmbed)"

head2 "Scanning the tree"
set +e
TREE_OUT="$(cd "$REPO_ROOT" && run_py treecheck.py "$CODERANK_MODEL_DIR" "$WORK" 2>"$WORK/tree.err")"
TREE_RC=$?
set -e
if (( TREE_RC != 0 )); then
  TREE_KIND="$(head -n1 "$WORK/tree.err" | cut -f1)"
  TREE_MSG="$(head -n1 "$WORK/tree.err" | cut -f2-)"
  tail -n +2 "$WORK/tree.err"
  printf '\n'
  case "$TREE_KIND" in
    not-absolute|bad-root)
      fail "$TREE_MSG" \
           "the sidecar rejects relative paths, hub IDs, URLs and symlinked roots before it loads anything" \
           "pass the canonical absolute path of a real directory" ;;
    hub-cache)
      fail "$TREE_MSG" \
           "hub caches are symlink farms and are mutated by any later hub operation, so the digest pins would not survive" \
           "materialise a snapshot outside the cache and point the wizard at that" ;;
    cache-inside-tree)
      fail "$TREE_MSG" \
           "model.sha256 covers every regular file recursively, so a cache written during or after verification silently changes the pinned identity" \
           "remove the listed entries from the tree (or re-materialise a clean snapshot) and re-run" ;;
    symlink-or-special)
      fail "$TREE_MSG" \
           "the sidecar refuses to hash or load a tree containing symlinks or special files" \
           "replace each symlink with the real file it points at, then re-run" ;;
    custom-code)
      fail "$TREE_MSG" \
           "trust_remote_code=True executes this model's own code; a target outside the verified tree could be fetched or loaded from elsewhere" \
           "review the auto_map / modules.json entries named above; do not serve this tree until they resolve inside it" ;;
    tokenizer-digest)
      fail "$TREE_MSG" \
           "tokenizer.sha256 pins the admission tokenizer independently of the model tree" \
           "confirm the tokenizer files sit at the root of the model directory; a different layout must be reviewed before extending the reference implementation" ;;
    *)
      fail "${TREE_MSG:-model tree check failed}" \
           "an unverifiable tree cannot produce trustworthy digest pins" \
           "resolve the error above and re-run" ;;
  esac
fi
printf '%s\n' "$TREE_OUT"

CODERANK_MODEL_ROOT="$(cat "$WORK/model_root")"
printf '\n'
ok "tree is absolute, symlink-free, cache-free and scannable"
write_env CODERANK_MODEL_DIR "$CODERANK_MODEL_DIR"
write_env CODERANK_MODEL_ROOT "$CODERANK_MODEL_ROOT"
printf '\n'
pause "Press Enter to continue."

# ── Stage 3 ───────────────────────────────────────────────────────────────
stage "Digest pins"

say "These are the pins from the protocol document's reproduction recipe,"
say "computed by the sidecar module's own tree_digest / tokenizer_digest /"
say "runtime_digest / runtime_versions functions. Nothing here is recomputed"
say "independently."
printf '\n'

MODEL_SHA256="$(cat "$WORK/model_sha256")"
TOKENIZER_SHA256="$(cat "$WORK/tokenizer_sha256")"
INSTRUCTION_SHA256="$(cat "$WORK/instruction_sha256")"

head2 "Pins for coderank.json"
printf '  model.sha256              %s\n' "$MODEL_SHA256"
printf '  tokenizer.sha256          %s\n' "$TOKENIZER_SHA256"
printf '  runtime.name              sentence-transformers\n'
printf '  runtime.version           %s\n' "$RUNTIME_VERSION"
printf '  runtime.sha256            %s\n' "$RUNTIME_SHA256"
printf '  query.instruction_sha256  %s\n' "$INSTRUCTION_SHA256"
printf '\n'
note "Recording a digest pins observed bytes or versions. It does not establish"
note "their provenance — review that before using these pins for a qualification."
printf '\n'

write_env CODERANK_MODEL_SHA256 "$MODEL_SHA256"
write_env CODERANK_TOKENIZER_SHA256 "$TOKENIZER_SHA256"
printf '\n'
pause "Press Enter to continue."

# ── Stage 4 ───────────────────────────────────────────────────────────────
stage "Manifest inputs"

say "Four things are yours to supply: the immutable revisions, the admission"
say "limit, the loopback endpoint, and where coderank.json lives."
printf '\n'

head2 "Artifact identity"
note "revision must be the exact immutable revision (a full commit SHA for a hub"
note "repository). A branch or tag name is not immutable and is not a pin."
ask_valid CODERANK_MODEL_ID "model.id:" \
  '^[^[:space:]]+$' "a nonempty identifier without whitespace, e.g. nomic-ai/CodeRankEmbed"
ask_valid CODERANK_MODEL_REVISION "model.revision:" \
  '^[^[:space:]]+$' "a nonempty immutable revision without whitespace"
ask_valid CODERANK_TOKENIZER_ID "tokenizer.id:" \
  '^[^[:space:]]+$' "a nonempty identifier without whitespace"
ask_valid CODERANK_TOKENIZER_REVISION "tokenizer.revision:" \
  '^[^[:space:]]+$' "a nonempty immutable revision without whitespace"

for pair in "model.revision:$CODERANK_MODEL_REVISION" "tokenizer.revision:$CODERANK_TOKENIZER_REVISION" \
            "model.id:$CODERANK_MODEL_ID" "tokenizer.id:$CODERANK_TOKENIZER_ID"; do
  value="${pair#*:}"
  case "$value" in
    REPLACE-*|*REPLACE-WITH*)
      fail "${pair%%:*} is still the example placeholder ($value)" \
           "the example manifest is a deliberately non-live template; its placeholders name no real artifact" \
           "substitute the real value from the source you provisioned the tree from" ;;
  esac
done
for pair in "model.revision:$CODERANK_MODEL_REVISION" "tokenizer.revision:$CODERANK_TOKENIZER_REVISION"; do
  value="${pair#*:}"
  if ! [[ "$value" =~ ^[0-9a-f]{40}$ ]]; then
    warn "${pair%%:*} is not a 40-character commit SHA — make sure it is genuinely immutable"
  fi
done

head2 "Admission limit"
note "Use the verified tokenizer/runtime's actual usable limit and reserve. The"
note "manifest accepts a positive limit and a nonnegative reserve, but validation"
note "does NOT establish the model's real context capacity — that is your call."
note "The sidecar does not subtract reserve again: max_tokens is already usable."
ask_valid CODERANK_MAX_TOKENS "admission.max_tokens:" \
  '^[1-9][0-9]{0,6}$' "a positive integer, e.g. 8192"
ask_valid CODERANK_RESERVE "admission.reserve (0 if preparation needs no special-token headroom):" \
  '^(0|[1-9][0-9]{0,6})$' "a nonnegative integer"
if (( CODERANK_RESERVE >= CODERANK_MAX_TOKENS )); then
  fail "admission.reserve ($CODERANK_RESERVE) is not smaller than admission.max_tokens ($CODERANK_MAX_TOKENS)" \
       "a reserve at or above the usable limit leaves no room for any document" \
       "lower the reserve, or raise max_tokens to the tokenizer's real usable limit"
fi
note "admission.algorithm is fixed at first-n-tokens / version 1: the reference"
note "sidecar accepts no other pair."

head2 "Loopback endpoint"
note "The endpoint must be an HTTP loopback origin with no credentials, path,"
note "query or fragment. serve binds only literal 127.0.0.1 or ::1."
ask_valid CODERANK_BIND "bind address (127.0.0.1 or ::1):" \
  '^(127\.0\.0\.1|::1)$' "exactly 127.0.0.1 or ::1 — serve accepts nothing else"
ask_valid CODERANK_PORT "port (1-65535):" \
  '^[1-9][0-9]{0,4}$' "a port between 1 and 65535"
if (( CODERANK_PORT > 65535 )); then
  fail "port $CODERANK_PORT is above 65535" "the endpoint would fail manifest validation" "choose a port between 1 and 65535"
fi
if [[ "$CODERANK_BIND" == "::1" ]]; then
  CODERANK_ENDPOINT="http://[::1]:$CODERANK_PORT"
else
  CODERANK_ENDPOINT="http://$CODERANK_BIND:$CODERANK_PORT"
fi
ok "endpoint: $CODERANK_ENDPOINT"

head2 "Manifest location"
note "coderank.json must live OUTSIDE the model directory: model.sha256 covers"
note "every regular file in that tree, so a manifest stored inside it would"
note "change the very digest it pins."
ask_valid CODERANK_MANIFEST "Absolute path for coderank.json:" \
  '^/.*\.json$' "an absolute path ending in .json, e.g. /srv/models/coderank.json"

MANIFEST_PARENT="$(dirname -- "$CODERANK_MANIFEST")"
if [[ ! -d "$MANIFEST_PARENT" ]]; then
  warn "$MANIFEST_PARENT does not exist"
  if confirm "Create it?"; then
    mkdir -p -- "$MANIFEST_PARENT"
  else
    fail "manifest directory $MANIFEST_PARENT does not exist" \
         "the manifest cannot be written, so nothing downstream can be validated" \
         "create the directory yourself, or choose a different path, then re-run"
  fi
fi
MANIFEST_DIR="$(cd -- "$MANIFEST_PARENT" && pwd -P)"
if [[ "$MANIFEST_DIR" == "$CODERANK_MODEL_ROOT" || "$MANIFEST_DIR" == "$CODERANK_MODEL_ROOT"/* ]]; then
  fail "the manifest path is inside the model directory ($CODERANK_MODEL_ROOT)" \
       "model.sha256 fingerprints every regular file in that tree; writing the manifest there invalidates the pin it contains, and every later verify would mismatch" \
       "choose a path outside the model tree, e.g. $(dirname -- "$CODERANK_MODEL_ROOT")/coderank.json"
fi
CODERANK_MANIFEST="$MANIFEST_DIR/$(basename -- "$CODERANK_MANIFEST")"
ok "manifest: $CODERANK_MANIFEST (outside the model tree)"

write_env CODERANK_MODEL_ID "$CODERANK_MODEL_ID"
write_env CODERANK_MODEL_REVISION "$CODERANK_MODEL_REVISION"
write_env CODERANK_TOKENIZER_ID "$CODERANK_TOKENIZER_ID"
write_env CODERANK_TOKENIZER_REVISION "$CODERANK_TOKENIZER_REVISION"
write_env CODERANK_MAX_TOKENS "$CODERANK_MAX_TOKENS"
write_env CODERANK_RESERVE "$CODERANK_RESERVE"
write_env CODERANK_BIND "$CODERANK_BIND"
write_env CODERANK_PORT "$CODERANK_PORT"
write_env CODERANK_ENDPOINT "$CODERANK_ENDPOINT"
write_env CODERANK_MANIFEST "$CODERANK_MANIFEST"
printf '\n'
pause "Press Enter to write the manifest."

# ── Stage 5 ───────────────────────────────────────────────────────────────
stage "Write coderank.json and verify it"

if [[ -f "$CODERANK_MANIFEST" ]]; then
  note "an existing manifest is at $CODERANK_MANIFEST"
fi

set +e
MK_OUT="$(cd "$REPO_ROOT" && run_py mkmanifest.py \
  "$CODERANK_MANIFEST" "$CODERANK_ENDPOINT" \
  "$CODERANK_MODEL_ID" "$CODERANK_MODEL_REVISION" "$MODEL_SHA256" \
  "$CODERANK_TOKENIZER_ID" "$CODERANK_TOKENIZER_REVISION" "$TOKENIZER_SHA256" \
  "$RUNTIME_VERSION" "$RUNTIME_SHA256" \
  "$CODERANK_MAX_TOKENS" "$CODERANK_RESERVE" "$INSTRUCTION_SHA256" 2>"$WORK/mk.err")"
MK_RC=$?
set -e
if (( MK_RC != 0 )); then
  cat "$WORK/mk.err"
  fail "the assembled manifest was rejected by the reference validator" \
       "the wizard refuses to write a manifest that cannot pass validate_manifest, so you never get a half-valid file on disk" \
       "correct the value named above and re-run"
fi

case "$MK_OUT" in
  unchanged) ok "manifest already byte-identical — left untouched" ;;
  written)   ok "wrote $CODERANK_MANIFEST" ;;
  *)         ok "manifest updated" ;;
esac

head2 "coderank_sidecar.py verify"
say "This re-reads the manifest from disk, rehashes the tree, re-scans the local"
say "custom code, and re-reads the installed runtime versions. It imports no"
say "inference runtime and loads no weights."
printf '\n'
note "$ python3 $(shq "$SIDECAR_PY") verify \\"
note "      --manifest $(shq "$CODERANK_MANIFEST") \\"
note "      --model-dir $(shq "$CODERANK_MODEL_ROOT")"
printf '\n'

set +e
VERIFY_OUT="$(cd "$REPO_ROOT" && python3 "$SIDECAR_PY" verify \
  --manifest "$CODERANK_MANIFEST" --model-dir "$CODERANK_MODEL_ROOT" 2>"$WORK/verify.err")"
VERIFY_RC=$?
set -e
if (( VERIFY_RC != 0 )); then
  warn "verify failed. It reports a single generic line by design:"
  printf '    %s\n' "$(cat "$WORK/verify.err")"
  head2 "Narrowing it down (same module, one check at a time)"
  (cd "$REPO_ROOT" && run_py diagnose.py "$CODERANK_MANIFEST" "$CODERANK_MODEL_ROOT") || true
  printf '\n'
  fail "coderank_sidecar.py verify rejected the manifest" \
       "verify is the gate between a manifest and a servable embedding space; a manifest that fails it cannot qualify anything" \
       "fix the first ✗ above, then re-run"
fi
printf '  %s\n' "$VERIFY_OUT"
printf '\n'
ok "verify passed: manifest, artifact hashes and installed runtime all match"

CODERANK_IDENTITY="$(cd "$REPO_ROOT" && run_py identity.py "$CODERANK_MANIFEST")"
write_env CODERANK_IDENTITY_DIGEST "$CODERANK_IDENTITY"
printf '\n'
pause "Press Enter to check the Go-side rules."

# ── Stage 6 ───────────────────────────────────────────────────────────────
stage "Go-side Manifest.Validate()"

say "The sidecar and GrapHi validate the same manifest independently. A manifest"
say "that only one of them accepts is not usable. This runs the real Go code —"
say "coderank.LoadManifest, which decodes strictly and calls Manifest.Validate()."
printf '\n'

command -v go >/dev/null 2>&1 || fail \
  "the go toolchain is not on PATH" \
  "Manifest.Validate() is the rule set the GrapHi adapter applies; skipping it means shipping a manifest the consumer may reject at qualification time" \
  "install Go and re-run, or run the check yourself against engine/embed/coderank"

GOCHECK_DIR="$(mktemp -d "$REPO_ROOT/.coderank-wizard-XXXXXX")"
GOCHECK_NAME="$(basename -- "$GOCHECK_DIR")"
cat > "$GOCHECK_DIR/main.go" <<'GO'
// Throwaway checker: loads a manifest through the real adapter code path.
package main

import (
	"fmt"
	"os"

	"github.com/samibel/graphi/engine/embed/coderank"
)

func main() {
	if len(os.Args) != 2 {
		fmt.Fprintln(os.Stderr, "usage: gocheck <manifest>")
		os.Exit(2)
	}
	m, err := coderank.LoadManifest(os.Args[1])
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	fmt.Println(m.IdentityDigest())
}
GO

set +e
GO_OUT="$(cd "$REPO_ROOT" && go run "./$GOCHECK_NAME" "$CODERANK_MANIFEST" 2>"$WORK/go.err")"
GO_RC=$?
set -e
rm -rf -- "$GOCHECK_DIR"; GOCHECK_DIR=""

if (( GO_RC != 0 )); then
  printf '  %s\n' "$(cat "$WORK/go.err")"
  printf '\n'
  fail "coderank.LoadManifest rejected the manifest" \
       "GrapHi's adapter applies these rules at construction: dimension 768, float32, l2, cpu, a loopback-only endpoint without credentials/path/query/fragment, nonempty pins, nonzero lowercase digests, and the exact pinned query instruction" \
       "correct the field named in the error above and re-run"
fi

ok "Manifest.Validate() accepted the manifest"
head2 "Durable identity, computed independently on both sides"
printf '  python (identity_digest)  %s\n' "$CODERANK_IDENTITY"
printf '  go     (IdentityDigest)   %s\n' "$GO_OUT"
if [[ "$GO_OUT" != "$CODERANK_IDENTITY" ]]; then
  printf '\n'
  fail "the Go and Python durable identity digests disagree" \
       "the adapter binds every attestation, admission and embedding response to its own computed digest; if the two implementations disagree, no response from this sidecar can ever be accepted" \
       "this is implementation drift, not an operator error — report it against engine/embed/coderank/manifest.go and scripts/eval/coderank_sidecar.py before using this manifest"
fi
printf '\n'
ok "both implementations agree on the durable identity"
printf '\n'
pause "Press Enter to start the sidecar."

# ── Stage 7 ───────────────────────────────────────────────────────────────
stage "Start serve in a separate terminal"

say "GrapHi never launches or supervises the sidecar, and neither does this"
say "wizard. serve runs in the foreground, holds the model in memory, and is"
say "stopped with Ctrl-C — it belongs to a terminal you own."
printf '\n'
warn "serve imports the runtime and executes the model's own local code"
warn "(trust_remote_code=True). Offline flags are not an OS sandbox. Review the"
warn "model code and configuration before you run this."
printf '\n'

head2 "Run this, exactly, in another terminal"
printf '\n'
printf '    python3 %s serve \\\n' "$(shq "$SIDECAR_PY")"
printf '      --manifest %s \\\n' "$(shq "$CODERANK_MANIFEST")"
printf '      --model-dir %s \\\n' "$(shq "$CODERANK_MODEL_ROOT")"
printf '      --bind %s --port %s\n' "$(shq "$CODERANK_BIND")" "$(shq "$CODERANK_PORT")"
printf '\n'
note "It verifies again immediately before importing the runtime, then repeats the"
note "complete tree, tokenizer, local-code and runtime verification after model"
note "construction. It fails closed if anything drifted. First start is slow."
note "Leave the model tree untouched while it runs."
printf '\n'

ATTEST_URL="$CODERANK_ENDPOINT/v1/attestation"
ATTEMPT=0
while :; do
  ATTEMPT=$((ATTEMPT + 1))
  pause "Started it? Press Enter to check liveness."
  printf '\n'
  note "$ curl --fail --silent $(shq "$ATTEST_URL")"
  set +e
  curl --fail --silent --show-error --max-time 10 --no-buffer \
    -o "$WORK/attestation.json" "$ATTEST_URL" 2>"$WORK/curl.err"
  CURL_RC=$?
  set -e
  if (( CURL_RC == 0 )); then
    head2 "Attestation"
    set +e
    ATTEST_OUT="$(cd "$REPO_ROOT" && run_py attest.py "$WORK/attestation.json" "$CODERANK_IDENTITY" 2>"$WORK/attest.err")"
    ATTEST_RC=$?
    set -e
    if (( ATTEST_RC == 0 )); then
      printf '%s\n' "$ATTEST_OUT"
      printf '\n'
      ok "the running sidecar serves exactly the manifest's embedding space"
      break
    fi
    cat "$WORK/attest.err"
    printf '\n'
    fail "the attestation does not match this manifest" \
         "every admission and embedding response carries the same binding; a mismatch means the process is serving a different model space, a different protocol, or is reporting values the adapter will refuse" \
         "stop that sidecar (Ctrl-C), confirm it was started with --manifest $(shq "$CODERANK_MANIFEST") and --model-dir $(shq "$CODERANK_MODEL_ROOT"), then re-run"
  fi
  warn "no answer from $ATTEST_URL"
  printf '    %s\n' "$(cat "$WORK/curl.err")"
  printf '\n'
  note "Common causes: serve is still loading the model; it exited (check that"
  note "terminal — it prints one line to stderr and exits nonzero on failure);"
  note "the port differs from the manifest endpoint; or it bound the other"
  note "loopback family (--bind $CODERANK_BIND must match the endpoint)."
  printf '\n'
  if (( ATTEMPT >= 10 )); then
    fail "the sidecar never answered after $ATTEMPT attempts" \
         "without a live, identity-bound attestation there is nothing to qualify against" \
         "read the error in the serve terminal, fix it, then re-run"
  fi
  if ! confirm "Try again?"; then
    fail "liveness not confirmed" \
         "the manifest is valid on both sides, but no process is proven to be serving it" \
         "start serve with the command above and re-run"
  fi
done

SERVING_EPOCH="$(cat "$WORK/attestation.json.epoch")"
printf '\n'
pause "Press Enter for the summary."

# ── Stage 8 ───────────────────────────────────────────────────────────────
stage "Durable identity and the process epoch"

head2 "Durable identity digest"
printf '\n    %s%s%s\n\n' "$BOLD" "$CODERANK_IDENTITY" "$RESET"
note "It covers schema, protocol, model, tokenizer, runtime, profile, admission"
note "and query pins. It deliberately excludes the endpoint and the process"
note "epoch, so the same pinned space can be relocated to another loopback port."
printf '\n'

head2 "Current process epoch"
printf '\n    %s\n\n' "$SERVING_EPOCH"
warn "Every restart of serve mints a NEW random epoch."
say "An adapter instance pins the epoch it was constructed with and rejects any"
say "later response carrying a different one — even when the artifact identity is"
say "byte-for-byte unchanged."
printf '\n'
step "Stopped or restarted the sidecar? Construct a fresh adapter instance."
step "Changed anything in the model tree, or the installed runtime? The pins are"
say  "    stale: re-run this wizard to recompute them before serving again."
printf '\n'
note "Hashes and self-attestation do not establish trust in a lying process, and"
note "protect nothing changed after the post-load check. Keep the tree immutable"
note "for the lifetime of the process."
printf '\n'
pause "Press Enter to finish."

finish
note "manifest:        $CODERANK_MANIFEST"
note "model tree:      $CODERANK_MODEL_ROOT"
note "endpoint:        $CODERANK_ENDPOINT"
note "identity digest: $CODERANK_IDENTITY"
note "process epoch:   $SERVING_EPOCH"
printf '\n'
note "The serve process is yours: it is still running in your other terminal."
note "Stop it with Ctrl-C when the qualification run is done."
printf '\n'
